"""Load the trained LSTM and run predictions. Kaggle is NOT needed during inference."""

import json
import re
from pathlib import Path

import torch
from tokenizers import Tokenizer
from model import NextWordLSTM


def load_model_files(model_dir: Path):
    """Load the three files generated by next-word-predict-LSTM.ipynb."""
    model_dir = Path(model_dir)
    with open(model_dir / "config.json", encoding="utf-8") as file:
        config = json.load(file)

    tokenizer = Tokenizer.from_file(str(model_dir / "tokenizer.json"))
    if tokenizer.get_vocab_size() != config["vocab_size"]:
        raise ValueError("Vocabulary size differs from config.json. Use files from one training run.")

    model = NextWordLSTM(
        vocab_size=config["vocab_size"],
        embed_dim=config["embed_dim"],
        hidden_size=config["hidden_size"],
        num_layers=config.get("num_layers", 1),
        dropout=config["dropout"],
        pad_id=config["pad_id"],
    )

    # Original Kaggle notebook saves state_dict() directly (not a full model).
    checkpoint = torch.load(
        model_dir / "best_lstm.pth", map_location="cpu", weights_only=True
    )
    # Also support older versions that wrap their weights under model_state.
    if isinstance(checkpoint, dict) and "model_state" in checkpoint:
        checkpoint = checkpoint["model_state"]
    model.load_state_dict(checkpoint)
    del checkpoint

    model.eval()  # disables dropout
    model.to("cpu")  # Streamlit Community Cloud normally has CPU only
    return model, tokenizer, config


def _ids_for_prompt(prompt, tokenizer, config):
    ids = tokenizer.encode(prompt.strip()).ids
    if not ids:
        raise ValueError("Please enter a sentence first.")
    seq_len = int(config["seq_len"])
    padded = ([int(config["pad_id"])] * seq_len + ids)[-seq_len:]
    return ids, padded


def predict_words(model, tokenizer, config, prompt, count=5):
    """Return [(word, probability), ...] using the trained LSTM."""
    _, padded = _ids_for_prompt(prompt, tokenizer, config)
    x = torch.tensor([padded], dtype=torch.long)

    with torch.inference_mode():
        logits = model(x)[0].float()

    # Match the notebook's word-only prediction: omit punctuation and special IDs.
    word_ids = [i for word, i in tokenizer.get_vocab().items() if word.isalpha()]
    if not word_ids:
        raise ValueError("Tokenizer contains no alphabetic tokens.")
    word_logits = logits[word_ids]
    probs = torch.softmax(word_logits, dim=0)
    values, indexes = torch.topk(probs, k=min(count, len(word_ids)))
    return [
        (tokenizer.id_to_token(word_ids[int(index)]), float(value))
        for value, index in zip(values.tolist(), indexes.tolist())
    ]


def _tidy_punctuation(text):
    text = re.sub(r"\s+([.,!?;:])", r"\1", text)
    text = re.sub(r"\s+(['’])\s+s\b", r"'s", text, flags=re.IGNORECASE)
    text = re.sub(r"\s+(['’])\s+t\b", r"'t", text, flags=re.IGNORECASE)
    text = re.sub(r"\s+([)])", r"\1", text)
    text = re.sub(r"([(])\s+", r"\1", text)
    return text.strip()


def generate_story(model, tokenizer, config, prompt, max_new_tokens=90,
                   temperature=0.85, top_k=15):
    """Continue the prompt by sampling likely tokens one by one."""
    ids, _ = _ids_for_prompt(prompt, tokenizer, config)
    generated = []

    pad_id = tokenizer.token_to_id("[PAD]")
    unk_id = tokenizer.token_to_id("[UNK]")
    eos_id = tokenizer.token_to_id("[EOS]")
    seq_len = int(config["seq_len"])

    with torch.inference_mode():
        for _ in range(max_new_tokens):
            padded = ([int(config["pad_id"])] * seq_len + ids)[-seq_len:]
            x = torch.tensor([padded], dtype=torch.long)
            logits = model(x)[0].float()

            for special_id in (pad_id, unk_id):
                if special_id is not None:
                    logits[special_id] = -float("inf")

            # Avoid ending the story immediately after the prompt.
            if eos_id is not None and len(generated) < 20:
                logits[eos_id] = -float("inf")

            logits /= max(float(temperature), 0.1)
            values, candidate_ids = torch.topk(logits, k=min(int(top_k), len(logits)))
            choice = torch.multinomial(torch.softmax(values, dim=0), 1).item()
            next_id = int(candidate_ids[choice].item())

            if eos_id is not None and next_id == eos_id:
                break

            ids.append(next_id)
            generated.append(next_id)

    continuation = tokenizer.decode(generated, skip_special_tokens=True)
    text = _tidy_punctuation(prompt.rstrip() + " " + continuation)
    return text, len(generated)
